x-width:1100px}.gallery-full .modal-head{background:#10263d;color:#fff;border-color:#ffffff20}.gallery-stage{display:grid;grid-template-columns:50px minmax(0,1fr) 50px;align-items:center;padding:20px 15px;gap:10px}.gallery-stage img{width:100%;height:65dvh;object-fit:contain}.gallery-stage .icon-btn{background:#ffffff20;border-color:#ffffff40;color:white}.gallery-counter{text-align:center;padding-bottom:20px;font-size:12px}.native-post{max-width:840px;margin:50px auto 80px}.native-post h1{font-size:36px;margin-bottom:25px}.native-post .post-body{margin-top:25px}.native-list{display:grid;gap:25px}.native-item{padding:24px;border:1px solid #e2e9f1;border-radius:10px}.native-item h2{font-size:23px;margin-bottom:12px}.native-item p{font-size:13px}.native-pagination{display:flex;justify-content:space-between;padding-top:25px}.ad-slot:empty{display:none}.ad-slot{margin:20px auto}.settings-bank{display:none}.widget h2.title{font-size:14px}body#layout .settings-bank{display:block}body#layout .public-ui,body#layout .footer,body#layout .header,body#layout .utility,body#layout dialog{display:none}body#layout .section{padding:12px}body#layout .settings-bank .section{display:block}body#layout .widget{display:block}body#layout .settings-bank:before{content:'SaeResidence — ubah logo, menu, hero, kontak, warna, dan agen melalui gadget di bawah.';display:block;padding:20px;background:#edf5ff}
