@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*,*:before,*:after{transition:none!important;animation:none!important}}

/* Real-estate icons: keep label and icon aligned at every size. */
.ico{display:inline-block;flex-shrink:0;vector-effect:non-scaling-stroke}.category-card>.ico{width:36px;height:36px;stroke-width:1.5}.round-icon{align-items:center;justify-content:center}.btn>[data-icon],.icon-btn>[data-icon]{display:inline-flex;align-items:center;justify-content:center}.step .ico,.intro-strip .ico{stroke-width:1.65}.detail-heading .btn[aria-pressed=true]{color:var(--accent,#0878e1)}@media(max-width:600px){.category-card>.ico{width:32px;height:32px}}

/* SaeResidence 1.3.0 — professional property detail experience */
:root{
  --ink:#18211d;
  --ink-soft:#34403a;
  --muted:#68716c;
  --paper:#f7f6f2;
  --surface:#fff;
  --line:#dfe3df;
  --line-strong:#cbd2cd;
  --brand-dark:#153d33;
  --warm:#b98b5f;
  --radius-control:8px;
  --radius-panel:12px;
  --shadow-float:0 18px 50px rgba(25,37,31,.10);
  --shadow-modal:0 28px 80px rgba(15,26,21,.22);
}
html{scroll-padding-top:84px}
body{background:var(--surface);color:var(--ink);font:15px/1.65 'Manrope',Arial,sans-serif;-webkit-font-smoothing:antialiased}
.sr-only{position:absolute!important;width:1px!important;height:1px!important;padding:0!important;margin:-1px!important;overflow:hidden!important;clip:rect(0,0,0,0)!important;white-space:nowrap!important;border:0!important}
h1,h2,h3,h4{color:var(--ink);font-weight:600;line-height:1.15;letter-spacing:-.025em}
h1,h2{font-family:'Newsreader',Georgia,serif;font-weight:500;letter-spacing:-.02em}
h2{font-size:clamp(32px,3vw,46px)}
h3{font-size:20px}
p{color:var(--muted)}
.wrap{width:min(1240px,calc(100% - 48px))}
.section{padding:96px 0}
.soft{background:var(--paper)}
.eyebrow{margin-bottom:12px;color:var(--accent,#1f5a49);font-size:11px;font-weight:700;letter-spacing:.12em;text-transform:uppercase}
.section-head{margin-bottom:38px;gap:32px;align-items:end}
.section-head p{max-width:560px;margin-top:13px;font-size:15px;line-height:1.7}
.btn{min-height:48px;padding:13px 22px;border-radius:var(--radius-control);background:var(--accent,#1f5a49);font-size:13px;font-weight:700;box-shadow:none;transition:background-color .18s,border-color .18s,color .18s,opacity .18s}
.btn:hover{background:var(--brand-dark);transform:none}
.btn.secondary{border-color:var(--line-strong);background:var(--surface);color:var(--ink)}
.btn.secondary:hover{border-color:var(--ink);background:var(--surface);color:var(--ink)}
.btn.dark{background:var(--ink)}
.btn.small{min-height:42px;padding:9px 15px}
.icon-btn{width:44px;height:44px;border-color:var(--line);border-radius:var(--radius-control);background:var(--surface);transition:background-color .18s,border-color .18s,color .18s}
.icon-btn:hover,.icon-btn[aria-pressed=true]{border-color:var(--accent,#1f5a49);background:#edf4f1;color:var(--accent,#1f5a49)}
.ico{stroke-width:1.65}
.text-link{color:var(--ink);font-size:13px;font-weight:700;text-decoration:underline;text-decoration-color:transparent;text-underline-offset:4px;transition:text-decoration-color .18s,color .18s}
.text-link:hover{color:var(--accent,#1f5a49);text-decoration-color:currentColor}
.utility{display:none}
.header{top:0;border-bottom:1px solid var(--line);background:rgba(255,255,255,.96);backdrop-filter:saturate(140%) blur(12px)}
.header-inner{height:76px;gap:32px}
.brand{gap:9px;color:var(--ink);font-size:21px;font-weight:750;letter-spacing:-.7px}
.brand .mark{width:31px;height:35px;color:var(--accent,#1f5a49)}
.brand span span{color:var(--accent,#1f5a49)}
.brand img{max-height:44px}
.nav{gap:5px;color:var(--ink-soft);font-size:13px;font-weight:650}
.nav>a,.nav>details>summary{padding:10px 12px;border-radius:8px;transition:color .18s ease,background .18s ease}
.nav>a:hover,.nav>details>summary:hover,.nav details[open]>summary{color:var(--accent,#1f5a49);background:var(--paper)}
.nav summary:after{content:'';width:6px;height:6px;margin:0 0 4px 3px;border-right:1.5px solid currentColor;border-bottom:1.5px solid currentColor;opacity:.62;transform:rotate(45deg);transform-origin:center;transition:transform .18s ease,opacity .18s ease}
.nav details[open]>summary:after{opacity:1;transform:rotate(225deg) translate(-1px,-1px)}
.nav>details:before{content:'';position:absolute;top:100%;left:-10px;right:-10px;height:12px;display:none}
.nav>details[open]:before{display:block}
.drop{top:calc(100% + 6px);left:-8px;min-width:230px;padding:8px;border-color:var(--line);border-radius:12px;box-shadow:0 18px 46px rgba(24,33,29,.13)}
.drop a{padding:10px 12px;border-radius:7px;line-height:1.35;font-weight:600}
.drop a:hover{background:var(--paper)}
.header-actions{gap:9px}
.header-actions>.btn{min-height:44px;padding:11px 18px}
.heart-count{top:-5px;right:-5px;background:var(--accent,#1f5a49)}

/* Hero: calm, direct and image-led. */
.hero{min-height:620px;background:#26342e;align-items:center}
.hero-photo{object-position:center 56%}
.hero:after{background:linear-gradient(90deg,rgba(16,31,26,.88) 0%,rgba(16,31,26,.67) 42%,rgba(16,31,26,.18) 77%,rgba(16,31,26,.05) 100%)}
.hero-copy{max-width:620px;padding:92px 0 138px}
.hero .eyebrow{display:block;color:#dce8e2;font-size:11px;letter-spacing:.14em}
.hero .eyebrow:before{display:none}
.hero h1{max-width:610px;color:#fff;font-size:clamp(46px,5.2vw,72px);font-weight:500;line-height:1.02;letter-spacing:-.025em}
.hero-copy p{max-width:520px;margin-top:24px;color:#e0e7e3;font-size:16px;line-height:1.75}
.hero-bottom{margin-top:32px;gap:22px}
.hero-bottom .btn{background:#fff;color:var(--ink)}
.hero-bottom .btn:hover{background:#f1f2ef;color:var(--ink)}
.hero-bottom .btn .ico{display:none}
.hero-note{color:#d5ded9;font-size:12px}
.hero-note .ico{color:#fff}
.photo-caption{display:none}

/* Search is the only elevated surface on the home page. */
.search-wrap{margin-top:-72px}
.search-box{padding:30px 32px 27px;border:1px solid var(--line);border-radius:var(--radius-panel);box-shadow:var(--shadow-float)}
.search-tabs{gap:0;margin-bottom:24px;border-bottom:1px solid var(--line)}
.search-tabs .pill{min-height:42px;margin-bottom:-1px;padding:9px 18px;border:0;border-bottom:2px solid transparent;border-radius:0;background:transparent;color:var(--muted)}
.search-tabs .pill[aria-pressed=true]{border-color:var(--accent,#1f5a49);background:transparent;color:var(--ink)}
.pill{min-height:42px;border-color:var(--line-strong);border-radius:var(--radius-control);background:var(--surface);font-size:12px;font-weight:650}
.pill[aria-pressed=true],.pill.active{border-color:var(--accent,#1f5a49);background:var(--accent,#1f5a49);color:#fff}
.fields{grid-template-columns:1.45fr 1fr 1fr auto;gap:16px}
.field{gap:8px}
.field>span,.field>label{color:var(--ink-soft);font-size:12px;font-weight:650}
.field input,.field select,.field textarea{min-height:52px;padding:12px 14px;border-color:var(--line-strong);border-radius:var(--radius-control);background:#fff;color:var(--ink);font-size:13px;outline:none;transition:border-color .18s,box-shadow .18s}
.field input:focus,.field select:focus,.field textarea:focus{border-color:var(--accent,#1f5a49);box-shadow:0 0 0 3px rgba(31,90,73,.12)}
.fields>.btn{min-height:52px;padding:13px 27px}
.advanced-line{margin-top:16px;color:var(--muted);font-size:12px}
.plain{min-height:40px;color:var(--ink-soft);font-size:12px;font-weight:650}
.advanced{margin-top:18px;padding-top:18px;border-color:var(--line)}
.intro-strip{gap:0;margin-top:44px;padding:25px 0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.intro-strip>div{padding:0 30px;border-right:1px solid var(--line)}
.intro-strip>div:first-child{padding-left:0}
.intro-strip>div:last-child{padding-right:0;border-right:0}
.intro-strip .round-icon{padding:0;background:transparent;color:var(--accent,#1f5a49)}
.intro-strip .round-icon .ico{width:25px;height:25px}
.intro-strip b{font-size:13px;font-weight:700}
.intro-strip p{margin-top:4px;font-size:12px}

/* Category and catalog surfaces. */
.category-grid{gap:0;border-top:1px solid var(--line);border-bottom:1px solid var(--line)}
.category-card{min-height:154px;padding:28px 24px;border:0;border-right:1px solid var(--line);border-radius:0;background:transparent;gap:22px;transition:background-color .18s,color .18s}
.category-card:last-child{border-right:0}
.category-card:hover{border-color:var(--line);background:var(--paper);box-shadow:none;transform:none}
.category-card>.ico{width:33px;height:33px;color:var(--accent,#1f5a49)}
.category-card .arrow{display:none}
.category-card b{font-size:15px;font-weight:700}
.category-card small{margin-top:5px;color:var(--muted);font-size:12px}
.catalog{scroll-margin-top:90px}
.catalog-tools{margin-bottom:28px;padding-bottom:20px;border-color:var(--line)}
.listing-tabs{gap:8px}
.listing-tabs .pill{padding:8px 16px;border-radius:var(--radius-control)}
.sort-views{gap:10px}
.sort-views select{min-height:42px;padding:8px 34px 8px 12px;border-color:var(--line-strong);border-radius:var(--radius-control);font-size:12px}
.view-switch{gap:6px}
.result-line{margin-bottom:22px;color:var(--muted);font-size:12px}
.properties{gap:24px}
.property-card{border-color:var(--line);border-radius:var(--radius-panel);box-shadow:none;transition:border-color .18s}
.property-card:hover{border-color:var(--line-strong);box-shadow:none;transform:none}
.card-photo{aspect-ratio:4/3;background:#e9ece9}
.card-photo img{transition:transform .3s ease}
.property-card:hover .card-photo img{transform:scale(1.02)}
.badges{left:15px;top:15px;gap:7px}
.badge{padding:6px 9px;border-radius:5px;background:rgba(255,255,255,.94);color:var(--ink);font-size:9px;font-weight:750;letter-spacing:.06em}
.badge.blue{background:var(--accent,#1f5a49)}
.badge.gold{background:#f3e7d8;color:#624a31}
.card-controls{right:14px;bottom:14px;gap:7px}
.card-controls .icon-btn{width:38px;height:38px;border:1px solid rgba(223,227,223,.95);border-radius:var(--radius-control);background:rgba(255,255,255,.94)}
.card-controls .ico{width:17px;height:17px}
.card-body{padding:22px 22px 20px}
.card-location{margin-bottom:10px;color:var(--muted);font-size:11px}
.property-card h3{font-size:18px;font-weight:650;line-height:1.4;letter-spacing:-.015em}
.property-card h3 a:hover{color:var(--accent,#1f5a49)}
.price{margin:13px 0 18px;color:var(--ink);font-size:21px;font-weight:750;letter-spacing:-.025em}
.price small{color:var(--muted);font-size:11px}
.specs{gap:17px;color:var(--ink-soft);font-size:12px}
.specs .ico{width:17px;height:17px;color:var(--muted)}
.card-footer{margin-top:20px;padding-top:16px;border-color:var(--line);color:var(--muted);font-size:11px}
.avatar{background:#e6efeb;color:var(--accent,#1f5a49)}
.card-footer a{color:var(--ink);font-weight:700}
.card-footer a:hover{color:var(--accent,#1f5a49)}
.notice{padding:13px 15px;border:1px solid #d9dfda;border-radius:var(--radius-control);background:#edf1ee;color:#46524c}
.empty{border-color:var(--line-strong);border-radius:var(--radius-panel);background:var(--surface)}

/* Editorial feature, areas, process and agents. */
.featured-layout{grid-template-columns:minmax(0,1.35fr) minmax(340px,.65fr);gap:64px}
.feature-photo{border-radius:var(--radius-panel);aspect-ratio:1.38}
.feature-photo .feature-tag{left:20px;bottom:20px;padding:10px 13px;border-radius:6px;background:rgba(255,255,255,.94);font-size:10px}
.feature-copy{padding:0}
.feature-copy h2{font-size:clamp(36px,4vw,52px)}
.feature-copy p{margin:20px 0 26px;font-size:15px;line-height:1.75}
.feature-copy .price{font-size:30px}
.feature-copy .btn .ico{display:none}
.location-grid{grid-template-columns:1.35fr 1fr 1fr;gap:18px}
.location-card{height:320px;border-radius:var(--radius-panel);background:var(--ink)}
.location-card:after{background:linear-gradient(180deg,transparent 25%,rgba(18,30,25,.82) 100%)}
.location-card:hover img{transform:scale(1.02)}
.location-card>span{left:24px;bottom:23px}
.location-card b{font-size:25px;font-weight:600}
.location-card small{margin-top:3px;color:#dce3df;font-size:12px}
.location-card .loc-arrow{display:none}
.how-grid{gap:0;border-top:1px solid var(--line)}
.step{padding:31px 32px 10px 0;border-right:1px solid var(--line)}
.step+.step{padding-left:32px}
.step:last-child{border-right:0}
.step .round-icon{padding:0;background:transparent;color:var(--accent,#1f5a49)}
.step .round-icon .ico{width:28px;height:28px}
.step-no{margin:28px 0 10px;color:var(--muted);font-size:10px;letter-spacing:.1em}
.step h3{font-size:21px}
.step p{margin-top:12px;font-size:13px;line-height:1.7}
.agent-grid{grid-template-columns:repeat(3,1fr);gap:24px}
.agent-card{border-color:var(--line);border-radius:var(--radius-panel)}
.agent-card .agent-photo{aspect-ratio:1.22;background:#e8ece9;color:#6b8277;font-size:44px}
.agent-card>div:last-child{padding:22px}
.agent-card h3{font-size:18px}
.agent-card p{margin:7px 0 14px;font-size:12px}
.agent-card .text-link{font-size:12px}
.agent-card .text-link .ico{display:none}
.contact-banner{padding:52px 56px;border-radius:var(--radius-panel);background:var(--brand-dark);gap:48px}
.contact-banner:after{display:none}
.contact-banner h2{color:#fff;font-size:clamp(32px,3vw,44px)}
.contact-banner p{margin-top:14px;color:#d0dcd7;font-size:14px}
.contact-banner .actions{gap:12px}
.contact-banner .btn:first-child{background:#fff;color:var(--ink)}
.contact-banner .btn:first-child:hover{background:#eef1ef}
.contact-banner .btn.secondary{border-color:rgba(255,255,255,.36);background:transparent;color:#fff}
.contact-banner .btn.secondary:hover{border-color:#fff;background:transparent;color:#fff}

/* Footer and overlays. */
.footer{padding-top:72px;background:#12241e;color:#b8c5bf;font-size:12px}
.footer-grid{grid-template-columns:1.7fr 1fr 1fr 1fr;gap:56px;padding-bottom:52px}
.footer .brand{color:#fff}
.footer p{margin-top:20px;color:#aebdb6;font-size:13px;line-height:1.75}
.footer h3{margin-bottom:20px;color:#fff;font-size:12px;font-weight:700}
.footer ul{gap:11px;font-size:12px}
.footer-bottom{padding:23px 0;border-color:rgba(255,255,255,.12);font-size:10px}
.backtop{right:22px;bottom:22px;width:42px;height:42px;box-shadow:0 8px 24px rgba(20,35,29,.16)}
.compare-bar{border-color:rgba(255,255,255,.16);border-radius:var(--radius-control);background:var(--brand-dark);box-shadow:0 12px 36px rgba(18,36,30,.23)}
.toast{top:94px;border-radius:var(--radius-control);background:var(--brand-dark);box-shadow:0 12px 32px rgba(18,36,30,.2)}
.modal{border-radius:var(--radius-panel);box-shadow:var(--shadow-modal);color:var(--ink)}
.modal::backdrop{background:rgba(12,22,18,.68);backdrop-filter:blur(2px)}
.modal-head{border-color:var(--line)}
.compare-table td,.compare-table th{border-color:var(--line)}
.compare-table th{background:var(--paper)}
.compare-table a{color:var(--accent,#1f5a49)}

/* Property detail: editorial content with a focused contact column. */
.detail-mode #detail-root{background:#f3f5f3}
.detail-hero{padding-bottom:44px;background:var(--surface)}
.crumb{padding:25px 0;color:var(--muted);font-size:11px}
.detail-heading{margin-bottom:30px;align-items:end}
.detail-heading h1{margin:13px 0 10px;font-size:clamp(36px,4vw,54px)}
.detail-heading p{font-size:13px}
.detail-heading .price{margin:0 0 14px;color:var(--ink);font-size:31px}
.detail-gallery{height:450px;gap:8px;border-radius:var(--radius-panel)}
.detail-gallery img{transition:transform .3s ease}
.detail-gallery button:hover img{transform:scale(1.02)}
.detail-gallery .gallery-count{border:1px solid var(--line);border-radius:6px;background:rgba(255,255,255,.94);font-size:11px}
.detail-content{grid-template-columns:minmax(0,1fr) 360px;gap:24px;padding:30px 0 96px}
.detail-nav{margin-bottom:10px;padding:0 0 19px;border-color:var(--line);color:var(--ink-soft);font-size:12px}
.detail-main>.panel{padding:30px;border:1px solid var(--line);border-radius:var(--radius-panel);margin:0 0 20px;background:var(--surface)}
.detail-main>.panel:last-child{border-bottom:1px solid var(--line)}
.panel h2{margin-bottom:23px;font-size:26px}
.overview{gap:0}
.overview>div{padding:0 24px;border-color:var(--line)}
.overview>div:first-child{padding-left:0}
.overview .ico{width:24px;height:24px;color:var(--accent,#1f5a49)}
.overview b{font-size:19px}
.overview small{font-size:11px}
.post-body{font-size:15px;line-height:1.85}
.post-body p{color:var(--muted)}
.details-grid{gap:0 28px;font-size:13px}
.details-grid>div{padding:13px 0;border-color:var(--line)}
.details-grid span{color:var(--muted)}
.amenities{gap:15px;font-size:13px}
.amenities .ico{color:var(--accent,#1f5a49)}
.map-frame{border-radius:var(--radius-control)}
.detail-side{top:96px}
.detail-side>.panel{padding:24px;border-color:var(--line);border-radius:var(--radius-panel);box-shadow:0 16px 42px rgba(25,37,31,.09)}
.detail-side>.panel:last-child{box-shadow:0 16px 42px rgba(25,37,31,.09)}
.contact-agent{padding-bottom:20px;border-bottom:1px solid var(--line)}
.contact-agent .avatar{background:#e6efeb;color:var(--accent,#1f5a49)}
.contact-form{display:grid;gap:10px;margin-top:20px}
.contact-form input,.contact-form textarea,.contact-form select{width:100%;min-width:0;border:1px solid var(--line-strong);border-radius:var(--radius-control);background:#fff;color:var(--ink);font-size:12px;padding:12px 13px;outline:0;transition:border-color .18s,box-shadow .18s}
.contact-form input,.contact-form select{min-height:46px}
.contact-form textarea{min-height:104px;line-height:1.55;resize:vertical}
.contact-form input:focus,.contact-form textarea:focus,.contact-form select:focus{border-color:var(--accent,#1f5a49);box-shadow:0 0 0 3px color-mix(in srgb,var(--accent,#1f5a49) 12%,transparent)}
.contact-consent{font-size:10px;line-height:1.55;margin:2px 0 3px}
.contact-actions{display:grid;grid-template-columns:1fr 1fr;gap:8px}
.contact-actions .btn{width:100%;min-height:44px;padding:10px 12px;font-size:11px}
.contact-actions .ico{width:17px;height:17px}
.contact-whatsapp{grid-column:1/-1}
.mobile-contact-bar{display:none}
.fine{color:var(--muted)!important;font-size:11px!important}
.kpr-result{border-radius:var(--radius-control);background:#edf3f0}
.kpr-result span{color:var(--muted)}
.kpr-result strong{color:var(--accent,#1f5a49)}
.gallery-full{background:#14231e}
.gallery-full .modal-head{background:#14231e}

@media(max-width:1100px){
  .wrap{width:calc(100% - 40px)}
  .nav{gap:18px}
  .header-inner{height:72px}
  .featured-layout{gap:38px}
  .detail-content{grid-template-columns:minmax(0,1fr) 310px;gap:30px}
  .footer-grid{gap:30px}
}
@media(max-width:900px){
  .nav{padding:22px;border-color:var(--line);box-shadow:0 16px 32px rgba(24,33,29,.1)}
  .nav>a,.nav>details>summary{width:100%;padding:11px 12px}
  .nav>details>summary{justify-content:space-between}
  .nav>details:before{display:none!important}
  .nav .drop{margin-top:6px;padding:7px;background:var(--paper);border:0;border-radius:10px;box-shadow:none}
  .nav .drop a{padding:10px 12px}
  .header-inner{height:70px}
  .hero{min-height:570px}
  .hero-copy{padding:78px 0 124px}
  .hero h1{font-size:clamp(46px,7vw,64px)}
  .fields{grid-template-columns:1fr 1fr}
  .properties{grid-template-columns:repeat(2,minmax(0,1fr))}
  .category-grid{grid-template-columns:repeat(3,1fr);border-bottom:0}
  .category-card{border-bottom:1px solid var(--line)}
  .category-card:nth-child(3){border-right:0}
  .featured-layout{grid-template-columns:1fr 1fr;gap:30px}
  .location-card{height:270px}
  .detail-content{grid-template-columns:1fr}
  .detail-side{position:static;display:block}
  .footer-grid{grid-template-columns:1.5fr 1fr 1fr}
  .section{padding:76px 0}
}
@media(max-width:600px){
  .wrap{width:calc(100% - 32px)}
  body{font-size:14px}
  .header-inner{height:66px}
  .brand{font-size:19px}
  .brand .mark{width:27px;height:31px}
  .header-actions .icon-btn{width:40px;height:40px}
  .hero{min-height:540px}
  .hero-photo{object-position:62% center}
  .hero:after{background:linear-gradient(90deg,rgba(16,31,26,.87),rgba(16,31,26,.48))}
  .hero-copy{padding:68px 0 112px}
  .hero h1{max-width:350px;font-size:44px;line-height:1.03}
  .hero-copy p{max-width:340px;margin-top:20px;font-size:14px;line-height:1.7}
  .hero-bottom{margin-top:27px}
  .hero-note{display:none}
  .search-wrap{margin-top:-54px}
  .search-box{padding:22px 20px;border-radius:10px}
  .search-tabs{margin-bottom:20px}
  .search-tabs .pill{padding:8px 9px;font-size:11px}
  .fields{gap:14px}
  .fields .field:first-child{grid-column:1/-1}
  .fields>.btn{grid-column:1/-1;min-height:50px}
  .advanced{grid-template-columns:1fr}
  .intro-strip{grid-template-columns:1fr;gap:0;margin-top:34px;padding:0;border-bottom:0}
  .intro-strip>div{padding:18px 0;border-right:0;border-bottom:1px solid var(--line)}
  .section{padding:64px 0}
  .section-head{margin-bottom:28px}
  h2{font-size:34px}
  .eyebrow{font-size:10px}
  .category-grid{grid-template-columns:1fr 1fr}
  .category-card{display:grid!important;min-height:142px;padding:23px 18px;border-right:1px solid var(--line)}
  .category-card:nth-child(even){border-right:0}
  .properties{grid-template-columns:1fr;gap:22px}
  .card-body{padding:21px 20px 19px}
  .property-card h3{font-size:18px}
  .price{font-size:22px}
  .catalog-tools{align-items:flex-start}
  .sort-views{width:100%;min-width:0}
  .sort-views label{flex:1;min-width:0}
  .sort-views select{width:100%;max-width:none}
  .view-switch{flex:0 0 auto}
  .featured-layout{grid-template-columns:1fr;gap:28px}
  .feature-photo{aspect-ratio:1.18}
  .feature-copy h2{font-size:38px}
  .location-grid{grid-template-columns:1fr;gap:14px}
  .location-card{height:250px}
  .how-grid{grid-template-columns:1fr;border-top:0}
  .step,.step+.step{display:block;padding:27px 0;border-top:1px solid var(--line);border-right:0}
  .step .round-icon{display:inline-flex}
  .step-no{margin:18px 0 8px}
  .step p{margin-top:10px}
  .agent-grid{grid-template-columns:1fr;gap:16px}
  .agent-card{display:grid;grid-template-columns:118px 1fr}
  .agent-card .agent-photo{height:100%;aspect-ratio:auto}
  .contact-banner{padding:34px 24px;gap:26px}
  .contact-banner .actions{flex-direction:column}
  .footer{padding-top:52px}
  .footer-grid{grid-template-columns:1fr 1fr;gap:34px 22px}
  .footer-grid>div:first-child{grid-column:1/-1}
  .footer-grid>div:last-child{grid-column:auto}
  .detail-heading{display:block}
  .detail-heading h1{font-size:38px}
  .detail-gallery{height:300px;gap:6px}
  .detail-content{padding:20px 0 92px}
  .detail-main>.panel{padding:24px 20px}
  .overview{grid-template-columns:1fr 1fr;gap:22px 0}
  .overview>div{padding:0 16px}
  .overview>div:nth-child(odd){padding-left:0}
  .overview>div:nth-child(2){border-right:0}
  .details-grid{grid-template-columns:1fr}
  .amenities{grid-template-columns:1fr 1fr}
  .detail-side{display:block}
  .detail-side>.panel{padding:24px 20px}
  .detail-mode{padding-bottom:76px}
  .mobile-contact-bar{position:fixed;z-index:80;left:0;right:0;bottom:0;display:flex;align-items:center;justify-content:space-between;gap:10px;min-height:72px;padding:10px max(14px,env(safe-area-inset-left)) calc(10px + env(safe-area-inset-bottom)) max(14px,env(safe-area-inset-right));border-top:1px solid var(--line);background:rgba(255,255,255,.97);box-shadow:0 -10px 30px rgba(25,37,31,.12);backdrop-filter:blur(12px)}
  .mobile-agent{display:flex;align-items:center;gap:9px;min-width:0}
  .mobile-agent .avatar{width:40px;height:40px;flex:0 0 auto;background:#e6efeb;color:var(--accent,#1f5a49);font-size:12px}
  .mobile-agent>span:last-child{display:grid;min-width:0}
  .mobile-agent b{max-width:118px;overflow:hidden;color:var(--ink);font-size:11px;text-overflow:ellipsis;white-space:nowrap}
  .mobile-agent small{max-width:118px;overflow:hidden;color:var(--muted);font-size:9px;text-overflow:ellipsis;white-space:nowrap}
  .mobile-contact-actions{display:flex;gap:7px;flex:0 0 auto}
  .mobile-contact-actions button{display:grid;place-items:center;width:44px;height:44px;padding:0;border:1px solid var(--line-strong);border-radius:8px;background:#fff;color:var(--ink)}
  .mobile-contact-actions button.contact-email{border-color:var(--accent,#1f5a49);background:var(--accent,#1f5a49);color:#fff}
  .mobile-contact-actions button:hover{border-color:var(--accent,#1f5a49);color:var(--accent,#1f5a49)}
  .mobile-contact-actions button.contact-email:hover{color:#fff;filter:brightness(.94)}
  .mobile-contact-actions .ico{width:19px;height:19px}
  .detail-mode .backtop{bottom:88px}
  .detail-mode .compare-bar{bottom:88px}
  .backtop{right:14px;bottom:14px}
}

@media(prefers-reduced-motion:reduce){
  html{scroll-behavior:auto}
  *,*:before,*:after{scroll-behavior:auto!important;transition:none!important;animation:none!important}
}

.sr-only{position:absolute;width:1px;height:1px;padding:0;margin:-1px;overflow:hidden;clip:rect(0,0,0,0);white-space:nowrap;border:0}.archive-mode .hero,.archive-mode .home-only,.single-mode #home-content,.error-mode #home-content{display:none}.archive-mode .search-wrap{margin-top:30px}.detail-mode .detail-gallery:has(button:only-child){grid-template-columns:1fr}.detail-mode .detail-gallery button:only-child{grid-row:auto}.detail-main .properties{grid-template-columns:repeat(2,minmax(0,1fr))}.ad-slot .widget-content:empty{display:none}.ad-slot:has(.widget-content:empty){display:none}@media(max-width:600px){.detail-main .properties{grid-template-columns:1fr}}

/* SaeResidence v1.2.2: centered mobile categories and readable type. */
@media (max-width:600px){
  body{font-size:15px;line-height:1.7}
  h2{font-size:clamp(30px,8.2vw,34px);line-height:1.22;letter-spacing:-.015em}
  .eyebrow{font-size:11px;line-height:1.5;letter-spacing:.1em}
  .hero h1{font-size:clamp(38px,11.2vw,44px);line-height:1.1}
  .hero-copy p,.section-head p,.intro-strip p,.feature-copy p,.step p,.contact-banner p{font-size:15px;line-height:1.75}
  .hero .eyebrow{font-size:11px;line-height:1.5;letter-spacing:.1em}
  .section-head{align-items:flex-start}
  #category-section .section-head{width:100%;align-items:center;text-align:center;gap:16px;margin-bottom:28px}
  #category-section .section-head>div{width:100%;min-width:0}
  #category-section .eyebrow{margin-bottom:10px}
  #category-section h2{text-wrap:balance;font-weight:500}
  #category-section .text-link{justify-content:center;white-space:normal;font-size:13px;line-height:1.5}
  #category-section .category-card{justify-items:center;text-align:center;gap:16px;min-height:154px;padding:22px 12px}
  #category-section .category-card b{font-size:16px;line-height:1.4;letter-spacing:-.01em}
  #category-section .category-card small{font-size:13px;line-height:1.5}
  #category-section .category-card:nth-child(odd){border-right:1px solid var(--line)}
  #category-section .category-card:nth-child(even){border-right:0}
  #category-section .category-card:last-child:nth-child(odd){grid-column:1/-1;justify-self:center;width:50%;border-right:0}
  .field input,.field select,.field textarea,.contact-form input,.contact-form select,.contact-form textarea{font-size:16px;line-height:1.5}
  .field>span,.field>label,.contact-form label>span{font-size:13px;line-height:1.5}
  .contact-consent{font-size:12px;line-height:1.6}
  .detail-heading h1{font-size:clamp(32px,9.7vw,38px);line-height:1.15;letter-spacing:-.02em}
  .detail-main .panel p{font-size:15px;line-height:1.75}
  .post-body{font-size:16px;line-height:1.8}
}

/* SaeResidence 1.3.0: place search, distance and radius. */
.map-tools{padding:26px;margin:0 0 24px;border:1px solid var(--line);border-radius:12px;background:#fff;min-width:0}
.map-tools-heading{display:flex;align-items:center;justify-content:space-between;gap:22px;margin-bottom:22px}
.map-tools-heading h3{font:700 18px/1.4 Manrope,Arial,sans-serif;letter-spacing:-.02em}
.map-tools-heading p{font-size:13px;line-height:1.6;margin-top:6px}
.map-tools-heading .btn{flex:0 0 auto;font-size:12px}
.map-controls{display:grid;grid-template-columns:minmax(0,1fr) 170px;gap:16px;align-items:end}
.map-place-form{display:flex;align-items:end;gap:10px;min-width:0}
.map-place-form .field{flex:1;min-width:0}
.map-place-form .btn{min-height:52px;flex:0 0 auto}
.map-search-status{font-size:13px;line-height:1.6;margin-top:14px;color:var(--ink-soft)}
.map-place-results{margin-top:15px;border:1px solid var(--line);border-radius:8px;overflow:hidden}
.map-place-results button{display:flex;align-items:center;gap:12px;padding:14px;width:100%;text-align:left;background:white;border:0;border-bottom:1px solid var(--line);color:var(--ink);min-height:60px}
.map-place-results button:last-child{border-bottom:0}
.map-place-results button:hover,.map-place-results button:focus-visible{background:var(--paper)}
.map-place-results button>span{flex:1;min-width:0;overflow-wrap:anywhere}
.map-place-results b{font-size:13px;line-height:1.5;display:block}
.map-place-results small{display:block;font-size:11px;line-height:1.5;color:var(--muted);margin-top:3px}
.map-focus-summary{display:flex;align-items:center;justify-content:space-between;gap:20px;background:#edf3f0;padding:16px;margin-top:18px;border-radius:8px}
.map-focus-summary>div:first-child{min-width:0;overflow-wrap:anywhere}
.map-focus-summary strong{font-size:14px;line-height:1.5}
.map-focus-summary p{font-size:12px;line-height:1.6;margin-top:4px}
.map-focus-actions{display:flex;gap:18px;flex:0 0 auto}
.map-focus-actions .plain{font-size:12px;text-decoration:underline;text-underline-offset:3px}
.map-privacy{font-size:11px;line-height:1.7;margin-top:16px}
.map-privacy a{text-decoration:underline;text-underline-offset:2px}
.distance-tag{display:flex;align-items:center;gap:6px;margin-top:12px;color:var(--accent,#1f5a49);font-size:12px;font-weight:650;line-height:1.5}
.distance-tag .ico{width:15px;height:15px}
.map-property-popup{display:grid;gap:8px;max-width:230px;font:13px/1.5 Manrope,Arial,sans-serif}
.map-property-popup img{width:230px;height:115px;object-fit:cover;border-radius:6px}
.map-property-popup strong{font-size:15px}
.map-property-popup span,.map-property-popup small{font-size:12px;color:#5c6861}
.map-property-popup a{font-weight:700;color:#1f5a49;text-decoration:underline}
.map-no-results{position:absolute;top:14px;left:54px;right:14px;z-index:500;background:#fff;padding:12px 14px;border-radius:7px;font-size:12px;line-height:1.6;box-shadow:0 3px 14px #19395122;pointer-events:none}
@media(max-width:768px){.map-tools-heading{align-items:flex-start}.map-tools-heading .btn{max-width:190px}.map-focus-summary{align-items:flex-start;flex-direction:column;gap:8px}}
@media(max-width:600px){
  .map-tools{padding:20px 16px}
  .map-tools-heading{display:block;margin-bottom:20px}
  .map-tools-heading h3{font-size:18px}
  .map-tools-heading p{font-size:14px}
  .map-tools-heading .btn{margin-top:16px;max-width:none;width:100%;font-size:13px;min-height:48px}
  .map-controls{grid-template-columns:minmax(0,1fr);gap:16px}
  .map-place-form{display:grid;grid-template-columns:minmax(0,1fr);gap:10px}
  .map-place-form .btn{width:100%;min-height:48px}
  .map-search-status{font-size:13px}
  .map-radius-field{max-width:none}
  .map-place-results b{font-size:14px}
  .map-place-results small,.map-privacy{font-size:12px}
  .map-focus-actions{flex-wrap:wrap;gap:10px 20px}
  .map-focus-summary strong{font-size:14px}
  #map-canvas,.map-panel iframe{height:390px}
  .map-panel{min-height:390px}
  .map-total{max-width:calc(100% - 24px);font-size:11px}
}

/* SaeResidence 1.3.1: one visible search hub with a map below it. */
.search-hub{background:#fff;border:1px solid var(--line);border-radius:12px;box-shadow:var(--shadow-float);overflow:hidden;scroll-margin-top:94px}
.search-hub .search-box{box-shadow:none;border:0;border-bottom:1px solid var(--line);border-radius:0}
.search-hub #map-tools{border:0;border-radius:0;margin:0;padding:26px 32px;background:#fcfdfb}
.search-hub .map-tools-heading{margin-bottom:18px}
.search-hub .map-tools-heading h3{font-size:18px}
.search-hub .map-controls{grid-template-columns:minmax(0,1fr) 120px auto;gap:14px}
.search-hub #map-nearby{min-height:52px;white-space:nowrap;font-size:12px;padding:12px 17px}
.search-hub .map-privacy{margin-top:12px}
.search-hub .map-search-status{margin-top:12px}
.search-map-stage{margin-top:22px;border:1px solid var(--line);border-radius:12px;background:#fff;overflow:hidden;scroll-margin-top:94px}
.search-map-heading{display:flex;align-items:center;justify-content:space-between;gap:20px;padding:20px 24px}
.search-map-heading h3{font:700 18px/1.4 Manrope,Arial,sans-serif;letter-spacing:-.02em}
.search-map-heading p{font-size:13px;line-height:1.5;margin-top:5px}
.search-map-actions{display:flex;align-items:center;gap:22px}
.search-map-actions .plain{font-size:12px;text-decoration:underline;text-underline-offset:3px}
.search-map-stage .map-panel{position:relative;top:auto;width:100%;min-height:460px;border:0;border-top:1px solid var(--line);border-radius:0}
.search-map-stage #map-canvas,.search-map-stage .map-panel iframe{height:460px}
@media(max-width:900px){
  .search-hub .map-controls{grid-template-columns:minmax(0,1fr) 130px}
  .search-hub .map-place-form{grid-column:1/-1}
  .search-hub .map-radius-field{grid-column:2;grid-row:2}
  .search-hub #map-nearby{grid-column:1;grid-row:2;justify-self:start}
}
@media(max-width:600px){
  .search-hub .search-box{padding:22px 18px}
  .search-hub{scroll-margin-top:82px}
  .search-hub #map-tools{padding:22px 18px}
  .search-hub .map-tools-heading{display:flex;align-items:flex-start;gap:12px;margin-bottom:18px}
  .search-hub .map-tools-heading h3{font-size:17px}
  .search-hub .map-tools-heading p{font-size:13px;line-height:1.6}
  .search-hub #toggle-search-map{width:auto;min-height:40px;margin:0;flex:0 0 auto;font-size:11px;padding:8px 10px}
  .search-hub #toggle-search-map .ico{display:none}
  .search-hub .map-controls{grid-template-columns:minmax(0,1fr) 94px;gap:14px 10px}
  .search-hub .map-place-form{display:grid;grid-template-columns:minmax(0,1fr) auto;align-items:end;gap:8px}
  .search-hub .map-place-form .field{grid-column:1}
  .search-hub .map-place-form .btn{width:auto;min-height:52px;padding:12px 10px;font-size:12px;white-space:nowrap}
  .search-hub #map-nearby{width:100%;justify-self:stretch;font-size:12px;padding:11px 8px;gap:6px}
  .search-hub #map-nearby .ico{width:16px;height:16px}
  .search-hub .map-privacy{font-size:11px;line-height:1.6}
  .search-map-heading{padding:18px;display:block}
  .search-map-actions{margin-top:12px;justify-content:space-between;gap:12px}
  .search-map-actions .text-link{font-size:12px;white-space:normal}
  .search-map-stage{scroll-margin-top:82px;margin-top:18px}
  .search-map-stage .map-panel{min-height:360px}
  .search-map-stage #map-canvas,.search-map-stage .map-panel iframe{height:360px}
}

/* SaeResidence 1.3.2: a single query and submit action. */
.search-hub .unified-search{border:0;padding:28px 32px}
.unified-query{margin:0 0 18px}
.unified-query input{min-height:54px}
.unified-filters{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr) 150px 170px;gap:14px;align-items:end}
.unified-filters>.btn{min-height:52px;margin:0;width:100%}
.unified-filters #map-nearby{grid-column:auto;grid-row:auto;justify-self:stretch}
.unified-search .advanced-line{margin-top:18px}
.unified-search #toggle-search-map{display:inline-flex;gap:7px;min-height:40px;margin:0;padding:0;font-size:12px;white-space:nowrap}
.unified-search #map-tools{padding:0;margin:14px 0 0;background:transparent;border:0;border-radius:0}
.unified-search .map-search-status{margin-top:0;font-size:13px;line-height:1.6}
.unified-search .map-privacy{margin-top:12px}
.unified-place-options{margin-top:14px}
.unified-place-options select{width:100%;min-width:0}
.unified-summary-controls{display:flex;align-items:center;gap:24px;flex:0 0 auto}
.unified-summary-controls .field{width:110px}
.unified-summary-controls .field select{min-height:42px;padding:8px 12px}
.unified-search .map-focus-summary{margin-top:16px}
.unified-search .map-focus-actions{gap:16px}
@media(max-width:900px){
 .unified-filters{grid-template-columns:repeat(2,minmax(0,1fr))}
 .unified-summary-controls{width:100%;justify-content:space-between;gap:16px}
}
@media(max-width:600px){
 .search-hub .unified-search{padding:22px 18px}
 .unified-query{margin-bottom:16px}
 .unified-filters{gap:14px 10px}
 .unified-filters>.btn{min-height:48px;font-size:13px;padding:11px 12px}
 .unified-search #toggle-search-map{width:auto;font-size:12px;padding:0;min-height:40px}
 .unified-search #map-nearby{width:100%;min-height:48px;font-size:12px;padding:11px 10px;white-space:nowrap}
 .unified-search .unified-support{padding:0!important}
 .unified-search .map-focus-summary{padding:14px}
 .unified-summary-controls{flex-wrap:wrap;align-items:end}
 .unified-summary-controls .field{width:100px}
 .unified-search .map-focus-actions{flex-wrap:wrap;gap:8px 16px}
 .unified-search .map-focus-actions .plain{font-size:12px}
}


/* SaeResidence v1.3.3: ten categories with a compact, scrollable property menu. */
#category-section #categories{
  display:grid;
  grid-template-columns:repeat(5,minmax(0,1fr));
  gap:0;
  border:0;
  border-top:1px solid var(--line,#dce4dd);
  border-left:1px solid var(--line,#dce4dd);
}
#category-section #categories>.category-card{
  display:grid;
  min-width:0;
  width:auto;
  min-height:146px;
  grid-column:auto;
  justify-self:stretch;
  justify-items:start;
  align-content:start;
  gap:16px;
  padding:24px 20px;
  border:0;
  border-right:1px solid var(--line,#dce4dd);
  border-bottom:1px solid var(--line,#dce4dd);
  text-align:left;
}
#category-section #categories>.category-card>span{min-width:0;max-width:100%}
#category-section #categories>.category-card b{
  display:block;
  font-size:15px;
  line-height:1.4;
  letter-spacing:-.01em;
  white-space:normal;
  word-break:normal;
  text-wrap:balance;
}
#category-section #categories>.category-card small{
  display:block;
  margin-top:5px;
  font-size:12px;
  line-height:1.5;
}
#category-section #categories>.category-card[aria-pressed=true]{
  background:#edf3ef;
  color:var(--accent,#1f5a49);
}

#main-nav .drop.property-menu{
  left:50%;
  right:auto;
  width:360px;
  min-width:0;
  max-width:calc(100vw - 32px);
  max-height:min(70vh,480px);
  max-height:min(70dvh,480px);
  padding:12px;
  display:grid;
  grid-template-columns:minmax(0,1fr);
  gap:0;
  transform:translateX(-50%);
  overflow-y:auto;
  overscroll-behavior:contain;
}
#main-nav .property-menu-primary{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:4px;
}
#main-nav .property-menu-primary>a:first-child{grid-column:1/-1;font-weight:750}
#main-nav .property-menu-primary>a,
#main-nav .property-category-menu>a{
  display:flex;
  align-items:center;
  min-width:0;
  min-height:44px;
  padding:10px 11px;
  border-radius:6px;
  font-size:13px;
  line-height:1.4;
  white-space:normal;
  word-break:normal;
}
#main-nav .property-menu-label{
  display:block;
  margin-top:10px;
  padding:13px 11px 9px;
  border-top:1px solid var(--line,#dce4dd);
  color:var(--muted,#66736c);
  font-size:10px;
  font-weight:700;
  line-height:1.5;
  letter-spacing:.08em;
  text-transform:uppercase;
}
#main-nav .property-category-menu{
  display:grid;
  grid-template-columns:repeat(2,minmax(0,1fr));
  gap:4px;
  min-width:0;
}
#main-nav .property-category-menu>a{gap:8px}
#main-nav .property-category-menu>a>[data-icon]{display:inline-flex;flex:0 0 18px}
#main-nav .property-category-menu>a .ico{width:18px;height:18px;margin:0}
#main-nav .property-category-menu>a[aria-current=page]{
  background:#edf3ef;
  color:var(--accent,#1f5a49);
}
#search-form .unified-filters .field:has(select[name=type]){min-width:0}
#search-form select[name=type]{width:100%;min-width:0;max-width:100%}

@media(max-width:900px){
  #category-section #categories{grid-template-columns:repeat(2,minmax(0,1fr))}
  #category-section #categories>.category-card{
    min-height:132px;
    padding:21px 14px;
    justify-items:center;
    gap:12px;
    text-align:center;
  }
  #category-section #categories>.category-card>.ico{width:30px;height:30px}
  #main-nav.is-open{
    gap:4px;
    max-height:calc(100vh - 82px);
    max-height:calc(100dvh - 82px);
    padding:12px 16px 18px;
    overflow-y:auto;
    overscroll-behavior:contain;
    scrollbar-gutter:stable;
  }
  #main-nav>a,#main-nav>details>summary{min-height:44px}
  #main-nav .drop.property-menu{
    position:static;
    left:auto;
    right:auto;
    top:auto;
    width:100%;
    min-width:0;
    max-width:none;
    max-height:none;
    margin:7px 0 5px;
    padding:8px;
    border:1px solid var(--line,#dce4dd);
    border-radius:8px;
    background:var(--paper,#f6f7f3);
    box-shadow:none;
    transform:none;
    overflow:visible;
  }
  #main-nav .property-menu-primary>a,#main-nav .property-category-menu>a{padding:10px;font-size:13px}
  #main-nav .property-menu-label{margin-top:8px;padding:11px 10px 8px}
  #search-form select[name=type]{padding:12px 8px}
}
@media(max-width:600px){
  #category-section #categories>.category-card b{font-size:16px;line-height:1.4}
  #category-section #categories>.category-card small{font-size:13px;line-height:1.5}
  #category-section #categories>.category-card:last-child:nth-child(odd){
    grid-column:auto;
    justify-self:stretch;
    width:auto;
    border-right:1px solid var(--line,#dce4dd);
  }
}

.footer-category-links{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:10px 14px}.footer-category-links li{min-width:0}.footer-category-links a{display:block;overflow-wrap:anywhere}.footer-category-links a[aria-current=page]{text-decoration:underline;font-weight:700}


/* SaeResidence 1.4.0 - native Blogger Layout only.
   The widget order follows the template DOM. No controls or positions are fabricated. */
body#layout{
  box-sizing:border-box;
  margin:0 auto;
  padding:22px 18px 42px;
  max-width:980px;
  min-width:0;
  background:#f3f6f1;
  color:#24382c;
  font:13px/1.55 Arial,sans-serif;
}
body#layout .settings-bank,
body#layout .layout-bank{
  display:block!important;
  width:auto;
  min-width:0;
  max-width:none;
  margin:0;
  padding:0;
}
body#layout .settings-bank:before{
  content:'SaeResidence - Tata Letak';
  display:block;
  margin:0 0 20px;
  padding:20px 22px;
  border:1px solid #1f5a49;
  border-radius:9px;
  background:#1f5a49;
  color:#fff;
  font:700 20px/1.35 Arial,sans-serif;
}
body#layout .layout-guide{
  margin:0 0 20px;
  padding:16px 18px;
  border:1px solid #d4dfd2;
  border-radius:8px;
  background:#fff;
  color:#556750;
  font-size:12px;
  line-height:1.65;
}
body#layout .layout-guide strong{color:#1f5a49}
body#layout .layout-guide p{margin:6px 0 0;color:inherit}
body#layout .settings-bank>.section,
body#layout .layout-stage,
body#layout #main,
body#layout #SaeAd{
  display:block!important;
  float:none;
  clear:both;
  width:auto;
  min-width:0;
  max-width:none;
  margin:0 0 18px;
  padding:12px;
  border:1px solid #cedbcd;
  border-radius:9px;
  background:#fff;
}
body#layout .layout-stage>h4,
body#layout .settings-bank>.section>h4,
body#layout #main>h4,
body#layout #SaeAd>h4{
  display:block;
  margin:0 0 12px;
  padding:10px 12px;
  border:0;
  border-bottom:1px solid #dbe5d8;
  background:#edf3eb;
  color:#1f5a49;
  font:700 13px/1.5 Arial,sans-serif;
  letter-spacing:0;
}
body#layout .settings-bank .widget,
body#layout .layout-stage .widget,
body#layout #main .widget,
body#layout #SaeAd .widget{
  display:block;
  float:none;
  clear:both;
  min-width:0;
  max-width:100%;
  margin:8px 0;
  border-color:#d4dfd1;
  border-radius:6px;
  background:#fff;
  box-shadow:none;
}
body#layout .settings-bank .widget:hover,
body#layout .layout-stage .widget:hover{border-color:#96b195}
body#layout .widget h2.title{
  color:#2c4935;
  font:700 13px/1.5 Arial,sans-serif;
  letter-spacing:0;
}
body#layout .editlink,
body#layout .add_widget a,
body#layout .add-widget a{
  color:#1f5a49;
  text-decoration:underline;
  text-underline-offset:2px;
}
body#layout .layout-stage .no-items,
body#layout .settings-bank>.section.no-items{border-color:#c2d1be}
body#layout .wrap{width:auto;max-width:none;min-width:0}
@media(max-width:620px){
  body#layout{padding:12px 10px 28px}
  body#layout .settings-bank:before{padding:16px;font-size:18px}
  body#layout .layout-guide{padding:12px 14px}
  body#layout .settings-bank>.section,
  body#layout .layout-stage,
  body#layout #main,
  body#layout #SaeAd{padding:9px;margin-bottom:14px}
}


/* Configuration helpers never appear on the public site. */
.layout-guide{display:none}
body#layout .layout-guide{display:block}
body#layout .settings-bank:not(#SaeLayoutMain):before{display:none}
body#layout .sae-layout-legacy-note{margin-top:10px;margin-bottom:8px;font-size:11px}
#category-intro:empty{display:none}
/* Customer logo and brand names must fit beside the mobile menu controls. */
@media(max-width:900px){
  .header-inner>.brand{min-width:0;max-width:calc(100% - 102px);overflow:hidden}
  .header-inner>.brand>span{min-width:0;overflow:hidden;text-overflow:ellipsis}
  .header-inner>.brand img{max-width:100%;object-fit:contain}
  .header-actions{flex-shrink:0}
}


/* SaeResidence 1.4.2: one readable copyright line. */
.footer-bottom{justify-content:center;text-align:center;gap:0}
#copyright-line{min-width:0;max-width:100%;line-height:1.8;overflow-wrap:anywhere}
#copyright-line a{font-weight:600;text-decoration:underline;text-underline-offset:3px}

.tbd-license-gate[hidden],.tbd-license-shield[hidden],.tbd-license-status[hidden],#tbd-license-context[hidden]{display:none!important}
.tbd-license-gate,.tbd-license-gate *,.tbd-license-status,.tbd-license-status *{box-sizing:border-box}
.tbd-license-gate{position:fixed;inset:0;z-index:2147483000;display:grid;place-items:center;overflow:auto;padding:24px 16px;background:rgba(15,23,42,.55);font-family:Arial,system-ui,sans-serif;color:#172339;text-align:left;line-height:1.6}
.tbd-license-card{width:100%;max-width:460px;margin:auto;padding:30px;background:#fff;border:1px solid #e5eaf2;border-radius:22px;box-shadow:0 24px 80px #0f172a40}
.tbd-license-brand{display:inline-flex;align-items:center;gap:8px;color:#172339!important;text-decoration:none!important;font:bold 21px/1.3 Arial,sans-serif;letter-spacing:-.6px}
.tbd-license-brand b{color:#2456d9}.tbd-license-logo{position:relative;display:grid;place-items:center;width:30px;height:30px;border-radius:9px;color:#fff;background:#2456d9;font:bold 24px/1 Arial,sans-serif;letter-spacing:0}.tbd-license-logo>span{position:absolute;right:5px;bottom:5px;width:6px;height:6px;border-radius:50%;background:#ffb300}
.tbd-license-symbol{display:grid;place-items:center;width:54px;height:54px;margin-top:28px;margin-bottom:16px;border-radius:15px;background:#edf2ff;color:#2456d9}
.tbd-license-eyebrow{margin:0 0 8px!important;color:#526178;font:bold 11px/1.5 Arial,sans-serif;letter-spacing:1.3px}
.tbd-license-card h2{margin:0 0 14px!important;padding:0;color:#172339;font:bold 26px/1.25 Arial,sans-serif;letter-spacing:-.7px;overflow-wrap:anywhere}
.tbd-license-card #tbd-license-description{margin:0 0 24px!important;color:#526178;font:15px/1.7 Arial,sans-serif;overflow-wrap:anywhere}
.tbd-license-card strong{color:#172339;font-weight:700}
.tbd-license-actions{display:grid;gap:10px}
.tbd-license-actions a{display:flex;justify-content:center;align-items:center;min-height:48px;padding:12px 16px;border:1px solid #2456d9;border-radius:11px;background:#2456d9;color:#fff!important;text-decoration:none!important;font:bold 15px/1.45 Arial,sans-serif;text-align:center;overflow-wrap:anywhere}
.tbd-license-actions a:hover{background:#173fa9;border-color:#173fa9}.tbd-license-actions .tbd-license-secondary{background:#fff;color:#2456d9!important;border-color:#d3ddef}.tbd-license-actions .tbd-license-secondary:hover{background:#f5f7fb}
#tbd-license-check{display:block;margin:18px auto 0;padding:6px 3px;border:0;background:transparent;color:#526178;font:14px/1.5 Arial,sans-serif;text-align:center;text-decoration:underline;text-underline-offset:4px;cursor:pointer}
.tbd-license-gate :focus-visible,.tbd-license-status button:focus-visible{outline:3px solid #9db5ff;outline-offset:3px}
.tbd-license-modal{overflow:hidden}.tbd-license-shield{position:fixed;inset:0;z-index:2147482000;background:transparent}
.tbd-license-status{position:fixed;z-index:2147483001;left:50%;bottom:18px;transform:translateX(-50%);width:calc(100% - 32px);max-width:440px;padding:16px 18px;border:1px solid #e5eaf2;border-radius:12px;background:#fff;color:#526178;box-shadow:0 6px 30px #0f172a20;font:14px/1.6 Arial,sans-serif}
.tbd-license-status button{display:block;margin-top:8px;padding:7px 12px;border:0;border-radius:8px;background:#2456d9;color:#fff;font:bold 13px/1.5 Arial,sans-serif;cursor:pointer}
@media(max-width:380px){.tbd-license-card{padding:24px 20px}.tbd-license-card h2{font-size:23px}}


/* tb-identity-presentation-b-20261107 */
[data-tb-logo-mirror] img{display:block;width:auto;max-width:100%;height:auto;max-height:48px;object-fit:contain} .tb-identity-wordmark{font:700 28px/1.2 Arial,sans-serif;white-space:nowrap}
.header-inner>.brand img{width:auto;height:auto;max-width:200px;max-height:48px;object-fit:contain}.footer .brand img{width:auto;height:auto;max-width:220px;max-height:56px;object-fit:contain}@media(max-width:600px){.header-inner>.brand img{max-width:170px;max-height:42px}}

/* Native license input is invisible on the public site. */
.tb-license-settings{display:none!important}

